package com.itemdroplookup;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;

@ConfigGroup("itemdroplookup")
public interface ItemDropLookupConfig extends Config
{
}

package com.itemdroplookup;

import com.google.inject.Provides;
import com.itemdroplookup.service.DropLookupService;
import com.itemdroplookup.service.ItemPriceLookupService;
import com.itemdroplookup.service.ItemSourceLookupService;
import com.itemdroplookup.service.MonsterLocationLookupService;
import com.itemdroplookup.ui.ItemDropLookupPanel;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
        name = "Item Drop Lookup"
)
public class ItemDropLookupPlugin extends Plugin
{
    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private DropLookupService dropLookupService;

    @Inject
    private ItemSourceLookupService itemSourceLookupService;

    @Inject
    private ItemPriceLookupService itemPriceLookupService;

    @Inject
    private MonsterLocationLookupService monsterLocationLookupService;

    private ItemDropLookupPanel panel;
    private NavigationButton navButton;

    @Override
    protected void startUp() throws Exception
    {
        panel = new ItemDropLookupPanel(dropLookupService, itemSourceLookupService, itemPriceLookupService, monsterLocationLookupService);

        BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        java.awt.Graphics2D graphics = icon.createGraphics();
        graphics.fillOval(2, 2, 12, 12);
        graphics.dispose();

        navButton = NavigationButton.builder()
                .tooltip("Item Drop Lookup")
                .icon(icon)
                .priority(5)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);

        log.debug("Item Drop Lookup started!");
    }

    @Override
    protected void shutDown() throws Exception
    {
        if (navButton != null)
        {
            clientToolbar.removeNavigation(navButton);
        }

        log.debug("Item Drop Lookup stopped!");
    }

    @Provides
    ItemDropLookupConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ItemDropLookupConfig.class);
    }
}

package com.itemdroplookup.model;

public class DropSource
{
    private final String itemName;
    private final String monsterName;
    private final String quantity;
    private final String dropRate;
    private final String notes;

    public DropSource(String itemName, String monsterName, String quantity, String dropRate, String notes)
    {
        this.itemName = itemName;
        this.monsterName = monsterName;
        this.quantity = quantity;
        this.dropRate = dropRate;
        this.notes = notes;
    }

    public String getItemName()
    {
        return itemName;
    }

    public String getMonsterName()
    {
        return monsterName;
    }

    public String getQuantity()
    {
        return quantity;
    }

    public String getDropRate()
    {
        return dropRate;
    }

    public String getNotes()
    {
        return notes;
    }
}

package com.itemdroplookup.model;

import java.util.ArrayList;
