package com.itemdroplookup.model;

import java.util.Collections;
import java.util.List;

/** One wiki location row. Missing classifications remain unknown. */
public final class MonsterLocation
{
    public enum Wilderness
    {
        YES, NO, UNKNOWN
    }

    private String id;
    private String monsterName;
    private String sourcePage;
    private long revisionId;
    private String npcName;
    private String location;
    private List<Integer> levels;
    private String levelsText;
    private Boolean members;
    private List<String> leagueRegions;
    private Wilderness wilderness;
    private String wildernessEvidence;
    private Boolean available;
    private Integer spawns;
    private String spawnCountBasis;
    private String notes;
    private String requirements;
    private List<String> dropVersions;
    private String version;
    private String sourceUrl;

    public String getId() { return id; }
    public String getMonsterName() { return monsterName; }
    public String getSourcePage() { return sourcePage; }
    public long getRevisionId() { return revisionId; }
    public String getNpcName() { return npcName; }
    public String getLocation() { return location; }
    public List<Integer> getLevels() { return readOnly(levels); }
    public String getLevelsText() { return levelsText; }
    public Boolean getMembers() { return members; }
    public List<String> getLeagueRegions() { return readOnly(leagueRegions); }
    public Wilderness getWilderness() { return wilderness == null ? Wilderness.UNKNOWN : wilderness; }
    public String getWildernessEvidence() { return wildernessEvidence; }
    public boolean isAvailable() { return Boolean.TRUE.equals(available); }
    public Integer getSpawns() { return spawns; }
    public String getSpawnCountBasis() { return spawnCountBasis; }
    public String getNotes() { return notes; }
    public String getRequirements() { return requirements; }
    public List<String> getDropVersions() { return readOnly(dropVersions); }
    public String getVersion() { return version; }
    public String getSourceUrl() { return sourceUrl; }

    private static <T> List<T> readOnly(List<T> values)
    {
        return values == null ? Collections.emptyList() : Collections.unmodifiableList(values);
    }
}

package com.itemdroplookup.service;

import java.util.Locale;
import java.util.Set;

/** Narrow exclusions for records that cannot provide ordinary-game acquisition. */
final class AcquisitionSourceRules
{
    // Each exact Wiki title was checked on 2026-11-02. All belong to the removed
    // Trailblazer Reloaded League relic family, including cache-only variants.
    // https://oldschool.runescape.wiki/w/Bloodthirsty
    // Keep the raw drop records unchanged; do not exclude by a name prefix.
    private static final Set<String> HISTORICAL_LEAGUE_NPCS = Set.of(
            "bloodthirsty abomination", "bloodthirsty abyssal demon", "bloodthirsty banshee",
            "bloodthirsty basilisk", "bloodthirsty basilisk sentinel", "bloodthirsty bloodveld",
            "bloodthirsty choke devil", "bloodthirsty cockathrice", "bloodthirsty crawler",
            "bloodthirsty drake", "bloodthirsty gargoyle", "bloodthirsty hand", "bloodthirsty hydra",
            "bloodthirsty infernal pyrelord", "bloodthirsty jelly", "bloodthirsty kurask",
            "bloodthirsty mage", "bloodthirsty mutated bloodveld", "bloodthirsty nechryarch",
            "bloodthirsty night beast", "bloodthirsty pyrelord", "bloodthirsty repugnant spectre",
            "bloodthirsty shadow wyrm", "bloodthirsty smoke devil", "bloodthirsty spectre",
            "bloodthirsty turoth", "bloodthirsty twisted banshee", "bloodthirsty warped jelly");
    private static final Set<String> ANIMATOR_METALS = Set.of("bronze", "iron", "steel", "black", "mithril", "adamant", "rune");

    private AcquisitionSourceRules() { }

    static boolean isOrdinaryDrop(String itemName, String monsterName)
    {
        String monster = monsterName.trim().toLowerCase(Locale.ROOT);
        if (HISTORICAL_LEAGUE_NPCS.contains(monster))
        {
            return false;
        }
        // Quest-encounter supplies are not an ordinary farming recommendation.
        // https://oldschool.runescape.wiki/w/Kamil (verified 2026-11-02)
        if ("kamil".equals(monster))
        {
            return false;
        }
        // The animator returns the player's supplied equipment. Preserve tokens.
        // https://oldschool.runescape.wiki/w/Animated_Adamant_Armour
        if (monster.startsWith("animated ") && monster.endsWith(" armour"))
        {
            String metal = monster.substring("animated ".length(), monster.length() - " armour".length());
            if (ANIMATOR_METALS.contains(metal))
            {
                String item = itemName.trim().toLowerCase(Locale.ROOT);
                return !item.equals(metal + " platebody") && !item.equals(metal + " platelegs")
                        && !item.equals(metal + " full helm");
            }
        }
        return true;
    }
}

package com.itemdroplookup.service;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.itemdroplookup.model.DropSource;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

@Singleton
public class DropLookupService
{
    private static final String DROPS_RESOURCE = "/wiki_monster_drops.json";

    private final Gson gson;
    private List<DropRecord> dropRecords;
    private Map<String, List<DropRecord>> recordsByItemName;

    @Inject
    public DropLookupService(Gson gson)
    {
        this.gson = gson;
    }

    public List<DropSource> searchByItemName(String itemName)
    {
        if (itemName == null || itemName.trim().isEmpty())
        {
            return Collections.emptyList();
        }

        String query = normalize(itemName);
        String resolvedQuery = resolveAlias(query);

        Set<DropRecord> matches = new LinkedHashSet<>();

        // 1. Exact item-name match.
        matches.addAll(getRecordsByItemName().getOrDefault(resolvedQuery, Collections.emptyList()));

        // 2. Compact normalized matching.
        // Compact matching ignores spaces, apostrophes, and punctuation so common
        // player input variations resolve to the same item:
        //   abyssalwhip  -> abyssal whip
        //   hydrasclaw   -> hydra's claw
        //   zulrahscales -> zulrah's scales
        //   brimstonekey -> brimstone key
        // Results are ranked: exact compact match, then starts-with, then contains.
        // Only the most specific non-empty tier is used, which keeps precise
        // matches from being diluted by broad substring hits.
        if (matches.isEmpty())
        {
            String compactQuery = compactNormalize(resolvedQuery);

            if (!compactQuery.isEmpty())
            {
                List<DropRecord> exactCompact = new ArrayList<>();
                List<DropRecord> startsWith = new ArrayList<>();
                List<DropRecord> contains = new ArrayList<>();

                for (Map.Entry<String, List<DropRecord>> entry : getRecordsByItemName().entrySet())
                {
                    String compactItem = compactNormalize(entry.getKey());
                    // Second variant with the possessive "'s" dropped, so the
                    // possessive s is optional: "Zulrah's scales" matches both
                    // "zulrahsscales" and "zulrahscales".
                    String compactItemNoPossessive = compactNormalizePossessive(entry.getKey());

                    if (compactItem.equals(compactQuery) || compactItemNoPossessive.equals(compactQuery))
                    {
                        exactCompact.addAll(entry.getValue());
                    }
                    else if (compactItem.startsWith(compactQuery) || compactItemNoPossessive.startsWith(compactQuery))
                    {
                        startsWith.addAll(entry.getValue());
                    }
                    else if (compactItem.contains(compactQuery) || compactItemNoPossessive.contains(compactQuery))
                    {
                        contains.addAll(entry.getValue());
                    }
                }

                if (!exactCompact.isEmpty())
                {
                    matches.addAll(exactCompact);
                }
                else if (!startsWith.isEmpty())
                {
                    matches.addAll(startsWith);
                }
                else
                {
                    matches.addAll(contains);
                }
            }
        }

        // 3. Strict typo fallback.
        // This runs only if exact/partial/compact matching found nothing.
        // It avoids broad false matches like runepouch -> rune javelin.
        if (matches.isEmpty() && resolvedQuery.length() >= 4)
        {
            for (Map.Entry<String, List<DropRecord>> entry : getRecordsByItemName().entrySet())
            {
                String item = entry.getKey();

                if (roughlyMatches(item, resolvedQuery))
                {
                    matches.addAll(entry.getValue());
                }
            }
        }

        return matches.stream()
                .filter(record -> AcquisitionSourceRules.isOrdinaryDrop(record.itemName, record.monsterName))
                .map(record -> new DropSource(
                        record.itemName,
                        record.monsterName,
                        record.quantity,
                        record.dropRate,
                        record.notes
                ))
                .sorted(Comparator.comparing(DropSource::getMonsterName, String.CASE_INSENSITIVE_ORDER))
                .collect(Collectors.toList());
    }

    private String resolveAlias(String query)
    {
        Map<String, String> aliases = new HashMap<>();

        // Keep this list for narrow/common slang only.
        // Avoid broad aliases like "whip" because they can mean multiple items.
        aliases.put("dboots", "dragon boots");
        aliases.put("d boots", "dragon boots");
        aliases.put("dragon boot", "dragon boots");

        aliases.put("tassets", "bandos tassets");
        aliases.put("tassies", "bandos tassets");
        aliases.put("bandos tass", "bandos tassets");
        aliases.put("bcp", "bandos chestplate");

        aliases.put("dchain", "dragon chainbody");
        aliases.put("d chain", "dragon chainbody");

        aliases.put("d med", "dragon med helm");
        aliases.put("dmed", "dragon med helm");

        aliases.put("rune scim", "rune scimitar");
        aliases.put("r scim", "rune scimitar");

        return aliases.getOrDefault(query, query);
    }

    private boolean roughlyMatches(String itemName, String query)
    {
        if (itemName.contains(query))
        {
            return true;
        }

        String[] queryWords = query.split("\\s+");
        String[] itemWords = itemName.split("\\s+");

        int meaningfulQueryWords = 0;
        int matchedWords = 0;

        for (String queryWord : queryWords)
        {
            if (queryWord.length() < 3)
            {
                continue;
            }

            meaningfulQueryWords++;

            for (String itemWord : itemWords)
            {
                if (itemWord.length() < 3)
                {
                    continue;
                }

                if (itemWord.startsWith(queryWord)
                        || isCloseTypo(itemWord, queryWord))
                {
                    matchedWords++;
                    break;
                }
            }
        }

        if (meaningfulQueryWords == 0)
        {
            return false;
        }

        return matchedWords == meaningfulQueryWords;
    }

    private boolean isCloseTypo(String itemWord, String queryWord)
    {
        if (Math.abs(itemWord.length() - queryWord.length()) > 2)
        {
            return false;
        }

        return levenshteinDistance(itemWord, queryWord) <= 1;
    }

    private int levenshteinDistance(String first, String second)
    {
        int[][] dp = new int[first.length() + 1][second.length() + 1];

        for (int i = 0; i <= first.length(); i++)
        {
            dp[i][0] = i;
        }

        for (int j = 0; j <= second.length(); j++)
        {
            dp[0][j] = j;
        }

        for (int i = 1; i <= first.length(); i++)
        {
            for (int j = 1; j <= second.length(); j++)
            {
                int cost = first.charAt(i - 1) == second.charAt(j - 1) ? 0 : 1;

                dp[i][j] = Math.min(
                        Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1),
                        dp[i - 1][j - 1] + cost
                );
            }
        }

        return dp[first.length()][second.length()];
    }

    private String normalize(String value)
    {
        return value.trim()
                .toLowerCase(Locale.ROOT)
                .replace("-", " ")
                .replace("_", " ")
                .replaceAll("\\s+", " ");
    }

    private String compactNormalize(String value)
    {
        return normalize(value)
                .replaceAll("[^a-z0-9]", "");
    }

    private String compactNormalizePossessive(String value)
    {
        // Drop a possessive "'s" at a word boundary (e.g. "Zulrah's scales" ->
        // "zulrah scales") before compacting. Used as an additional match variant
        // so possessive item names are searchable with or without the possessive s.
        return normalize(value)
                .replaceAll("'s\\b", "")
                .replaceAll("[^a-z0-9]", "");
    }

    private Map<String, List<DropRecord>> getRecordsByItemName()
    {
        if (recordsByItemName != null)
        {
            return recordsByItemName;
        }

        recordsByItemName = new HashMap<>();

        for (DropRecord record : getDropRecords())
        {
            if (record.itemName == null)
            {
                continue;
            }

            String itemName = normalize(record.itemName);
            recordsByItemName.computeIfAbsent(itemName, key -> new ArrayList<>()).add(record);
        }

        return recordsByItemName;
    }

    private List<DropRecord> getDropRecords()
    {
        if (dropRecords != null)
        {
            return dropRecords;
        }

        try (InputStream inputStream = DropLookupService.class.getResourceAsStream(DROPS_RESOURCE))
        {
            if (inputStream == null)
            {
                dropRecords = Collections.emptyList();
                return dropRecords;
            }

            InputStreamReader reader = new InputStreamReader(inputStream, StandardCharsets.UTF_8);
            Type listType = new TypeToken<List<DropRecord>>() {}.getType();

            dropRecords = gson.fromJson(reader, listType);

            if (dropRecords == null)
            {
                dropRecords = Collections.emptyList();
            }

            return dropRecords;
        }
        catch (Exception ex)
        {
            dropRecords = Collections.emptyList();
            return dropRecords;
        }
    }

    private static class DropRecord
    {
        private String itemName;
        private String monsterName;
        private String quantity;
        private String dropRate;
        private String notes;
    }
}

package com.itemdroplookup.service;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.itemdroplookup.model.ItemPrice;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.Map;
import java.util.HashMap;

@Singleton
public class ItemPriceLookupService
{
    private static final String PRICES_RESOURCE = "/ge_prices.json";

    private final Gson gson;
    private List<ItemPriceRecord> itemPriceRecords;
    private Map<String, String> potionFamilies;

    /** Verified potion families only: charged jewellery and waterskins are not doses. */
    public Optional<String> findPotionFamily(String itemName)
    {
        if (potionFamilies == null)
        {
            potionFamilies = new HashMap<>();
            try (InputStream stream = getClass().getResourceAsStream("/potion_families.json"))
            {
                if (stream != null)
                {
                    PotionFamilies data = gson.fromJson(new InputStreamReader(stream, StandardCharsets.UTF_8), PotionFamilies.class);
                    if (data != null && data.families != null)
                    {
                        data.families.forEach(name -> potionFamilies.put(potionKey(name), name));
                    }
                }
            }
            catch (Exception ex)
            {
                // Ordinary exact prices remain available if optional family data is absent.
            }
        }
        return itemName == null ? Optional.empty() : Optional.ofNullable(potionFamilies.get(potionKey(itemName)));
    }

    private String potionKey(String name)
    {
        // Preserve plus signs: Antidote+ and Antidote++ are different potions.
        return name.trim().replaceAll("\\([1-4]\\)$", "").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9+]", "");
    }

    private static class PotionFamilies
    {
        private List<String> families;
    }

    @Inject
    public ItemPriceLookupService(Gson gson)
    {
        this.gson = gson;
    }

    public Optional<ItemPrice> searchByItemName(String itemName)
    {
        if (itemName == null || itemName.trim().isEmpty())
        {
            return Optional.empty();
        }

        String query = normalize(itemName);
        String compactQuery = compactNormalize(itemName);

        return getItemPriceRecords().stream()
                .filter(record -> record.itemName != null)
                .filter(record ->
                {
                    String normalizedItem = normalize(record.itemName);
                    String compactItem = compactNormalize(record.itemName);

                    return normalizedItem.equals(query)
                            || compactItem.equals(compactQuery);
                })
                .findFirst()
                .map(record -> new ItemPrice(
                        record.itemName,
                        record.price,
                        record.highAlch,
                        record.tradeable,
                        record.notes
                ));
    }

    private String normalize(String value)
    {
        return value.trim()
                .toLowerCase(Locale.ROOT)
                .replace("-", " ")
                .replace("_", " ")
                .replaceAll("\\s+", " ");
    }

    private String compactNormalize(String value)
    {
        return normalize(value)
                .replaceAll("[^a-z0-9+]", "");
    }

    private List<ItemPriceRecord> getItemPriceRecords()
    {
        if (itemPriceRecords != null)
        {
            return itemPriceRecords;
        }

        try (InputStream inputStream = ItemPriceLookupService.class.getResourceAsStream(PRICES_RESOURCE))
        {
            if (inputStream == null)
            {
                itemPriceRecords = Collections.emptyList();
                return itemPriceRecords;
            }

            InputStreamReader reader = new InputStreamReader(inputStream, StandardCharsets.UTF_8);
            Type listType = new TypeToken<List<ItemPriceRecord>>() {}.getType();

            itemPriceRecords = gson.fromJson(reader, listType);

            if (itemPriceRecords == null)
            {
                itemPriceRecords = Collections.emptyList();
            }

            return itemPriceRecords;
        }
        catch (Exception ex)
        {
            itemPriceRecords = Collections.emptyList();
            return itemPriceRecords;
        }
    }

    private static class ItemPriceRecord
    {
        private String itemName;
        private String price;
        private String highAlch;
        private boolean tradeable;
        private String notes;
    }
}

package com.itemdroplookup.service;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.itemdroplookup.model.ItemSource;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

@Singleton
public class ItemSourceLookupService
{
    // Curated, hand-maintained non-NPC sources.
    private static final String CURATED_RESOURCE = "/item_sources.json";
    // Generated shop sources (tools/build_shop_sources.py). Optional: absent until generated.
    private static final String SHOP_RESOURCE = "/wiki_shop_sources.json";

    // Generated (wiki_shop_sources.json) records hidden at lookup time because a
    // higher-quality curated record supersedes them, or the generated cost/label is
    // misleading (e.g. a coin price that ignores a reward-point unlock).
    //
    // This is applied ONLY to generated records, never to curated ones, so a curated
    // record that happens to share an (itemName, sourceName) pair is unaffected.
    // Matching is exact on (itemName, sourceName), case-insensitive, and deliberately
    // narrow: it hides only the listed pairs, not every generated record for an item.
    // The generated JSON is left untouched.
    private static final Set<String> SUPPRESSED_GENERATED_SOURCES = buildSuppressedGeneratedSources();

    // This is a mid-raid resupply interaction, not an ordinary acquisition shop.
    // Its generated rows also misidentify Theatre points as coins. Keep it out
    // until raid-specific supplies have their own explicit product treatment.
    private static final String RAID_SUPPLY_CHEST = "Chest (Theatre of Blood)";
    private static final Pattern ZERO_DEFAULT_STOCK = Pattern.compile(
            "\\bDefault stock:\\s*0(?:\\.|\\s|$)", Pattern.CASE_INSENSITIVE);
    // Verified StoreTableHead currencies (Wiki revisions captured in the QA report).
    // These corrections are exact shop names, not guesses from shop categories.
    private static final Map<String, String> VERIFIED_CURRENCIES = Map.of(
            "TzHaar-Mej-Roh's Rune Store", "Tokkul",
            "Agility Arena Store", "Brimhaven vouchers",
            "Brimhaven Agility Arena Ticket Exchange", "discontinued Agility arena tickets",
            "Bounty Hunter Store", "Bounty Hunter points",
            "Justine's stuff for the Last Shopper Standing", "LMS points");

    private static Set<String> buildSuppressedGeneratedSources()
    {
        Set<String> suppressed = new HashSet<>();
        suppressed.add(suppressionKey("Graceful hood", "Grace's Graceful Clothing"));
        suppressed.add(suppressionKey("Rune pouch", "Slayer Rewards"));
        suppressed.add(suppressionKey("Rune pouch", "Justine's stuff for the Last Shopper Standing"));
        return suppressed;
    }

    private static String suppressionKey(String itemName, String sourceName)
    {
        return itemName.trim().toLowerCase(Locale.ROOT)
                + "|"
                + sourceName.trim().toLowerCase(Locale.ROOT);
    }

    private final Gson gson;
    private List<ItemSourceRecord> itemSourceRecords;

    @Inject
    public ItemSourceLookupService(Gson gson)
    {
        this.gson = gson;
    }

    public List<ItemSource> searchByItemName(String itemName)
    {
        if (itemName == null || itemName.trim().isEmpty())
        {
            return Collections.emptyList();
        }

        String query = normalize(itemName);
        String compactQuery = compactNormalize(itemName);

        return selectMostSpecificMatches(query, compactQuery).stream()
                .map(record -> new ItemSource(
                        record.itemName,
                        record.sourceType,
                        record.sourceName,
                        record.location,
                        record.cost,
                        record.notes,
                        record.packName, record.packItemName, record.packQuantity, record.packNoted
                ))
                .collect(Collectors.toList());
    }

    /**
     * Tiered matching that returns only the most specific non-empty tier, so a precise
     * query is not diluted by broad substring hits (e.g. "rune pouch" should not also
     * return "Rune pouch note"). Tiers, in order:
     *   1. exact normalized item-name match
     *   2. compact exact match (ignores spaces/punctuation: "runepouch" -> "rune pouch")
     *   3. starts-with match
     *   4. contains match
     * Records are scanned in load order (curated first, then generated and suppression-
     * filtered), so result order is stable within whichever tier is selected.
     */
    private List<ItemSourceRecord> selectMostSpecificMatches(String query, String compactQuery)
    {
        List<ItemSourceRecord> exact = new ArrayList<>();
        List<ItemSourceRecord> compactExact = new ArrayList<>();
        List<ItemSourceRecord> startsWith = new ArrayList<>();
        List<ItemSourceRecord> contains = new ArrayList<>();

        for (ItemSourceRecord record : getItemSourceRecords())
        {
            if (record.itemName == null)
            {
                continue;
            }

            String normalizedItem = normalize(record.itemName);
            String compactItem = compactNormalize(record.itemName);

            if (normalizedItem.equals(query))
            {
                exact.add(record);
            }
            else if (!compactQuery.isEmpty() && compactItem.equals(compactQuery))
            {
                compactExact.add(record);
            }
            else if (normalizedItem.startsWith(query))
            {
                startsWith.add(record);
            }
            else if (normalizedItem.contains(query))
            {
                contains.add(record);
            }
        }

        if (!exact.isEmpty())
        {
            return exact;
        }
        if (!compactExact.isEmpty())
        {
            return compactExact;
        }
        if (!startsWith.isEmpty())
        {
            return startsWith;
        }
        return contains;
    }

    private String normalize(String value)
    {
        return value.trim()
                .toLowerCase(Locale.ROOT)
                .replace("-", " ")
                .replace("_", " ")
                .replaceAll("\\s+", " ");
    }

    private String compactNormalize(String value)
    {
        return normalize(value)
                .replaceAll("[^a-z0-9]", "");
    }

    private List<ItemSourceRecord> getItemSourceRecords()
    {
        if (itemSourceRecords != null)
        {
            return itemSourceRecords;
        }

        // Curated sources first, then generated shop sources (if present). Both feed
        // the same searchable list; a missing generated file is treated as empty.
        // Suppression is applied only to the generated set so curated records — even
        // ones sharing an (itemName, sourceName) pair — are always kept.
        List<ItemSourceRecord> merged = new ArrayList<>();
        merged.addAll(loadRecords(CURATED_RESOURCE));
        merged.addAll(filterSuppressedGenerated(loadRecords(SHOP_RESOURCE)));
        // A zero-stock shop relies on player sales; it is not a reliable purchase
        // option. Filter before expanding packs so derived offers follow this rule.
        merged.removeIf(record -> record.sourceType != null
                && record.sourceType.toLowerCase(Locale.ROOT).endsWith("shop")
                && record.notes != null && ZERO_DEFAULT_STOCK.matcher(record.notes).find());

        itemSourceRecords = addPackOptions(merged);
        return itemSourceRecords;
    }

    private List<ItemSourceRecord> addPackOptions(List<ItemSourceRecord> records)
    {
        Map<String, PackRecord> packs = new HashMap<>();
        try (InputStream stream = getClass().getResourceAsStream("/item_packs.json"))
        {
            if (stream != null)
            {
                Type type = new TypeToken<List<PackRecord>>() {}.getType();
                List<PackRecord> definitions = gson.fromJson(new InputStreamReader(stream, StandardCharsets.UTF_8), type);
                if (definitions != null)
                {
                    definitions.forEach(pack -> packs.put(normalize(pack.packName), pack));
                }
            }
        }
        catch (Exception ex)
        {
            // The original source records remain usable if optional pack data is absent.
            return records;
        }
        List<ItemSourceRecord> expanded = new ArrayList<>();
        for (ItemSourceRecord record : records)
        {
            String currency = VERIFIED_CURRENCIES.get(record.sourceName);
            if (currency != null && record.cost != null)
            {
                record.cost = record.cost.replaceAll(" coins?$", " " + currency);
                if (!"Tokkul".equals(currency))
                {
                    record.sourceType = "Reward Shop";
                    record.notes = record.notes == null ? "" : record.notes.replace("Cost increases as stock depletes.", "").trim();
                }
                if (currency.startsWith("discontinued"))
                {
                    record.notes = "Requires old tickets that can no longer be earned. " + record.notes;
                }
                if ("Tokkul".equals(currency))
                {
                    record.notes = (record.notes == null ? "" : record.notes + " ") + "Karamja gloves reduce the price.";
                }
            }
            PackRecord pack = record.itemName == null ? null : packs.get(normalize(record.itemName));
            if (pack != null)
            {
                record.packName = pack.packName;
                record.packItemName = pack.itemName;
                record.packQuantity = pack.quantity;
                record.packNoted = pack.noted;
                if (pack.costByShop != null && pack.costByShop.containsKey(record.sourceName))
                {
                    record.cost = pack.costByShop.get(record.sourceName);
                    record.sourceType = "Reward Shop";
                    record.notes = pack.notes;
                }
            }
            expanded.add(record);
            if (pack != null)
            {
                ItemSourceRecord contents = new ItemSourceRecord();
                contents.itemName = pack.itemName;
                contents.sourceName = record.sourceName;
                contents.sourceType = record.sourceType;
                contents.location = record.location;
                contents.cost = record.cost;
                contents.notes = record.notes;
                contents.packName = record.packName;
                contents.packItemName = record.packItemName;
                contents.packQuantity = record.packQuantity;
                contents.packNoted = record.packNoted;
                expanded.add(contents);
            }
        }
        return expanded;
    }

    private List<ItemSourceRecord> filterSuppressedGenerated(List<ItemSourceRecord> records)
    {
        List<ItemSourceRecord> kept = new ArrayList<>();
        for (ItemSourceRecord record : records)
        {
            if (RAID_SUPPLY_CHEST.equalsIgnoreCase(record.sourceName))
            {
                continue;
            }
            if (record.itemName == null || record.sourceName == null
                    || !SUPPRESSED_GENERATED_SOURCES.contains(suppressionKey(record.itemName, record.sourceName)))
            {
                kept.add(record);
            }
        }
        return kept;
    }

    private List<ItemSourceRecord> loadRecords(String resource)
    {
        try (InputStream inputStream = ItemSourceLookupService.class.getResourceAsStream(resource))
        {
            if (inputStream == null)
            {
                return Collections.emptyList();
            }

            InputStreamReader reader = new InputStreamReader(inputStream, StandardCharsets.UTF_8);
            Type listType = new TypeToken<List<ItemSourceRecord>>() {}.getType();

            List<ItemSourceRecord> records = gson.fromJson(reader, listType);

            return records != null ? records : Collections.emptyList();
        }
        catch (Exception ex)
        {
            return Collections.emptyList();
        }
    }

    private static class ItemSourceRecord
    {
        private String itemName;
        private String sourceType;
        private String sourceName;
        private String location;
        private String cost;
        private String notes;
        private String packName;
        private String packItemName;
        private int packQuantity;
        private boolean packNoted;
    }

    private static class PackRecord
    {
        private String packName;
        private String itemName;
        private int quantity;
        private boolean noted;
        private Map<String, String> costByShop;
        private String notes;
    }
}

package com.itemdroplookup.service;

import com.itemdroplookup.model.DropSource;
import com.itemdroplookup.model.DropSourceGroup;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class MonsterFamilyGrouper
{
    // Matches a trailing parenthetical at end-of-string.
    // Greedy (.+) ensures the split is on the LAST paren group:
    //   "Skeleton (Barrows)"          -> parent "Skeleton"
    //   "Skeleton Hellhound (Vet'ion)" -> parent "Skeleton Hellhound"
    private static final Pattern TRAILING_PAREN = Pattern.compile("^(.+)\\s+\\(([^)]+)\\)$");

    private MonsterFamilyGrouper() {}

    /**
     * Groups a list of drop sources by monster family using trailing-parenthetical
     * parsing only. Member order within each group reflects the order of {@code sources}.
     * Bare base names ("Skeleton") automatically join the same family as parenthetical
     * variants ("Skeleton (Barrows)") because both produce the same parent string.
     */
    public static List<DropSourceGroup> group(List<DropSource> sources)
    {
        Map<String, List<DropSource>> byParent = new LinkedHashMap<>();

        for (DropSource source : sources)
        {
            String parent = extractParent(source.getMonsterName());
            byParent.computeIfAbsent(parent, k -> new ArrayList<>()).add(source);
        }

        List<DropSourceGroup> groups = new ArrayList<>(byParent.size());

        for (Map.Entry<String, List<DropSource>> entry : byParent.entrySet())
        {
            groups.add(new DropSourceGroup(entry.getKey(), entry.getValue()));
        }

        return groups;
    }

    static String extractParent(String monsterName)
    {
        if (monsterName == null)
        {
            return "";
        }

        Matcher m = TRAILING_PAREN.matcher(monsterName);

        if (m.matches())
        {
            return m.group(1);
        }

        return monsterName;
    }
}

package com.itemdroplookup.service;

import com.itemdroplookup.model.MonsterLocation;

/** The same location predicates are used in details and item results. */
public final class MonsterLocationFilter
{
    public enum WildernessFilter
    {
        ALL("All locations"), ONLY("Wilderness only"), EXCLUDE("Exclude Wilderness");

        private final String label;
        WildernessFilter(String label) { this.label = label; }
        @Override public String toString() { return label; }
    }

    public enum MembershipFilter
    {
        ALL("Any membership"), F2P("F2P locations"), MEMBERS("Members locations");

        private final String label;
        MembershipFilter(String label) { this.label = label; }
        @Override public String toString() { return label; }
    }

    private MonsterLocationFilter() { }

    public static boolean matches(MonsterLocation location, WildernessFilter wilderness,
                                  MembershipFilter membership)
    {
        if (wilderness == WildernessFilter.ONLY && location.getWilderness() != MonsterLocation.Wilderness.YES)
        {
            return false;
        }
        if (wilderness == WildernessFilter.EXCLUDE && location.getWilderness() != MonsterLocation.Wilderness.NO)
        {
            return false;
        }
        if (membership == MembershipFilter.F2P && !Boolean.FALSE.equals(location.getMembers()))
        {
            return false;
        }
        if (membership == MembershipFilter.MEMBERS && !Boolean.TRUE.equals(location.getMembers()))
        {
            return false;
        }
        return true;
    }
}

package com.itemdroplookup.service;

import com.google.gson.Gson;
import com.itemdroplookup.model.DropSource;
import com.itemdroplookup.model.MonsterLocation;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/** Offline, exact-page location lookup. Never falls back to a parent monster name. */
@Slf4j
@Singleton
public class MonsterLocationLookupService
{
    private final Gson gson;
    private static final Comparator<MonsterLocation> LOCATION_ORDER = Comparator
            .comparing(MonsterLocation::isAvailable).reversed()
            .thenComparing(MonsterLocation::getLocation, String.CASE_INSENSITIVE_ORDER)
            .thenComparing(location -> String.valueOf(location.getLevelsText()));
    private final Map<String, List<MonsterLocation>> byMonster = new HashMap<>();
    private final Map<List<String>, List<MonsterLocation>> byDrop = new HashMap<>();
    private boolean loaded;

    @Inject
    public MonsterLocationLookupService(Gson gson)
    {
        this.gson = gson;
    }

    public List<MonsterLocation> lookupByMonsterName(String monsterName)
    {
        loadOnce();
        return byMonster.getOrDefault(normalize(monsterName), Collections.emptyList());
    }

    public LocationMatch lookup(DropSource source)
    {
        loadOnce();
        List<MonsterLocation> verified = byDrop.get(key(source.getMonsterName(), source.getItemName(),
                source.getQuantity(), source.getDropRate(), source.getNotes()));
        return verified == null
                ? new LocationMatch(lookupByMonsterName(source.getMonsterName()), false)
                : new LocationMatch(verified, true);
    }

    public boolean hasQualifyingLocation(DropSource source, MonsterLocationFilter.WildernessFilter filter)
    {
        // Clearing the filter restores every source, including missing location data.
        if (filter == MonsterLocationFilter.WildernessFilter.ALL)
        {
            return true;
        }
        LocationMatch match = lookup(source);
        return match.isVerified() && match.getLocations().stream().anyMatch(location ->
                location.isAvailable() && MonsterLocationFilter.matches(location, filter,
                        MonsterLocationFilter.MembershipFilter.ALL));
    }

    private synchronized void loadOnce()
    {
        if (loaded)
        {
            return;
        }
        // First use is from the Swing sidebar, never from the RuneLite client thread.
        try (InputStream input = getClass().getResourceAsStream("/monster_locations.json"))
        {
            if (input == null)
            {
                log.debug("Bundled monster locations are unavailable");
                return;
            }
            Dataset dataset = gson.fromJson(new InputStreamReader(input, StandardCharsets.UTF_8), Dataset.class);
            if (dataset == null || dataset.schemaVersion != 1 || dataset.locations == null || dataset.dropBindings == null)
            {
                log.debug("Unsupported monster location dataset");
                return;
            }
            Map<String, MonsterLocation> byId = new HashMap<>();
            for (MonsterLocation location : dataset.locations)
            {
                if (location == null || location.getId() == null || location.getMonsterName() == null)
                {
                    continue;
                }
                byId.put(location.getId(), location);
                byMonster.computeIfAbsent(normalize(location.getMonsterName()), k -> new ArrayList<>()).add(location);
            }
            // Signatures can represent multiple table variants. Union all verified
            // associations, never arbitrarily choose the first one.
            Map<List<String>, Set<MonsterLocation>> associations = new HashMap<>();
            Set<List<String>> invalid = new LinkedHashSet<>();
            for (Binding binding : dataset.dropBindings)
            {
                List<String> signature = key(binding.monsterName, binding.itemName, binding.quantity, binding.dropRate, binding.notes);
                if (binding.locationIds == null || binding.locationIds.isEmpty())
                {
                    invalid.add(signature);
                    continue;
                }
                Set<MonsterLocation> locations = associations.computeIfAbsent(signature, k -> new LinkedHashSet<>());
                for (String id : binding.locationIds)
                {
                    MonsterLocation location = byId.get(id);
                    if (location == null || !normalize(location.getMonsterName()).equals(normalize(binding.monsterName)))
                    {
                        invalid.add(signature);
                    }
                    else
                    {
                        locations.add(location);
                    }
                }
            }
            associations.forEach((signature, locations) -> {
                if (!invalid.contains(signature) && !locations.isEmpty())
                {
                    List<MonsterLocation> ordered = new ArrayList<>(locations);
                    ordered.sort(LOCATION_ORDER);
                    byDrop.put(signature, Collections.unmodifiableList(ordered));
                }
            });
            byMonster.replaceAll((name, locations) -> {
                locations.sort(LOCATION_ORDER);
                return Collections.unmodifiableList(locations);
            });
        }
        catch (Exception ex)
        {
            byMonster.clear();
            byDrop.clear();
            log.debug("Unable to load bundled monster locations", ex);
        }
        finally
        {
            loaded = true;
        }
    }

    private static List<String> key(String monster, String item, String quantity, String rate, String notes)
    {
        return Arrays.asList(normalize(monster), normalize(item), normalize(quantity), normalize(rate), normalize(notes));
    }

    private static String normalize(String value)
    {
        return value == null ? "" : value.replace('_', ' ').replace('\u2019', '\'')
                .trim().toLowerCase(Locale.ROOT).replaceAll("\\s+", " ");
    }

    public static final class LocationMatch
    {
        private final List<MonsterLocation> locations;
        private final boolean verified;

        private LocationMatch(List<MonsterLocation> locations, boolean verified)
        {
            this.locations = locations;
            this.verified = verified;
        }

        public List<MonsterLocation> getLocations() { return locations; }
        public boolean isVerified() { return verified; }
    }

    private static class Dataset
    {
        private int schemaVersion;
        private List<MonsterLocation> locations;
        private List<Binding> dropBindings;
    }

    private static class Binding
    {
        private String monsterName;
        private String itemName;
        private String quantity;
        private String dropRate;
        private String notes;
        private List<String> locationIds;
    }
}

